def transform_template(g):
    h,w=len(g),len(g[0]); pts=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==8]
    r0=min(r for r,c in pts); c0=min(c for r,c in pts); pts=[(r-r0,c-c0) for r,c in pts]
    out=[row[:] for row in g]; H=max(r for r,c in pts); W=max(c for r,c in pts)
    for r in range(h-H):
      for c in range(w-W):
        if all(g[r+dr][c+dc]==0 for dr,dc in pts):
          for dr,dc in pts: out[r+dr][c+dc]=8
    return out
